import{z as l,x as s,o as e,c as p,q as B,j as n,D as a,d as r,s as o,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"复现的类型与目标","description":"","frontmatter":{"title":"复现的类型与目标","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-replication-types.md","filePath":"llm/rw-replication-types.md","lastUpdated":1791413859000}'),d={name:"llm/rw-replication-types.md"};function D(c,E,m,h,C,f){const t=s("Mermaid");return e(),p("div",null,[E[2]||(E[2]=B('<h1 id="复现的类型与目标" tabindex="-1">复现的类型与目标 <a class="header-anchor" href="#复现的类型与目标" aria-label="Permalink to &quot;复现的类型与目标&quot;">​</a></h1><div class="epigraph"><p>主张要成为共同事实，前提是别人也能把它造出来；造不出来的主张，只是某个人的私人经历。</p><footer>—— 据 Popper, The Logic of Scientific Discovery, 1959；Claerbout 与 Karrenbach, 1992 整理</footer></div><p><a href="/llm/ef-map">上一课</a>把评测前沿收在仪器、卷子、功效与私有评测的决策单上：评测回答「这个模型现在多好」。本课是「论文复现工作流」的第一课，回答它的前置问题：评测表里那个数字，别人能不能重新算出来。评测给出量尺，复现检验量尺上的刻度是否真实；两者的仪器观一脉相承，只是对象从模型换成了论文。后面的报告判读、走读、配置工程、归因与对齐，都默认你开工前已经写下两行字：这是一次什么类型的复现，它停在哪条目标线上。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「复现」被当成一个词用，底下至少压着两类不同的事。<strong>结果复现</strong>：拿作者的代码、数据与环境重跑，期望得到相同的数字；它的敌人是环境漂移——库版本、硬件、随机种子的路径。<strong>方法复现</strong>：不看作者实现，按论文描述独立实现同一方法，期望得到相同的结论；它的敌人是隐性决策——没写进论文的超参、数据清洗顺序、评测协议细节。两类失败的含义完全不同：前者失败指向披露不足或环境失配，后者失败可能指向论文本身过拟合到了它的评测。社区里 reproducibility 与 replicability 的用词之争，实质就是这两类工作没分开。</p><p><span class="marginnote">一句话分清两类：结果复现是「用原作者的菜谱和厨具，做出同一道菜」；方法复现是「只看菜谱文字、用自己的厨具独立做，要求味道结论一致」。前者考照图施工的能力，后者考对菜谱本身的理解。</span></p><p>目标同样要分线。<strong>数字线</strong>要求对上论文表格里的具体数值；<strong>结论线</strong>只要求复出相同的排序或主张（方法 A 优于方法 B）；<strong>能力线</strong>只要求下游可用水平达到声明。目标没定就开工，会在错误的标准上被审判：追数字的人抱怨实现不同，追结论的人被 0.3 分的差吓住。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开工前写一页复现声明，五项：类型（结果复现、方法复现或混合）、目标线（数字、结论、能力）、容差（差多少算对上：绝对差、相对差或置信区间重叠）、范围（只复主表还是全部表格）、约束（可用算力与期限）。这一页是整个课程的靶子，后课的每个锚点、每笔预算都指回它。</p><p><span class="marginnote">数字实例：一页声明写出来就五行——「类型：方法复现；目标线：结论线；容差：排序一致即算对上，分差 1 分内视为持平；范围：只复主表；约束：8 卡两周」。五分钟写完，却决定了后面每一笔算力往哪花、什么算失败。</span></p><p>类型决定读什么。结果复现的重心在代码与环境：种子、锁文件、数据快照，越逐位越好。方法复现的重心在报告与消融：作者声明了什么依赖，缺了什么披露，需要自己补哪些决策。目标线决定算力的花法：数字线最贵，往往绑定全量规模；结论线允许缩小规模，因为排序在小规模上常可保持；能力线以应用验收为准，不必对表格。</p>',11)),(e(),n(i,null,{default:a(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E8%AE%BA%E6%96%87%E4%B8%BB%E5%BC%A0%22%5D%20--%3E%20TYPE%7B%22%E7%B1%BB%E5%9E%8B%E5%88%A4%E5%AE%9A%22%7D%0A%20%20TYPE%20--%3E%7C%22%E7%BB%93%E6%9E%9C%E5%A4%8D%E7%8E%B0%22%7C%20RES%5B%22%E5%AF%B9%E9%BD%90%E7%8E%AF%E5%A2%83%E4%B8%8E%E7%A7%8D%E5%AD%90%22%5D%0A%20%20TYPE%20--%3E%7C%22%E6%96%B9%E6%B3%95%E5%A4%8D%E7%8E%B0%22%7C%20MET%5B%22%E8%A1%A5%E9%BD%90%E9%9A%90%E6%80%A7%E5%86%B3%E7%AD%96%22%5D%0A%20%20RES%20--%3E%20GOAL%5B%22%E7%9B%AE%E6%A0%87%E7%BA%BF%EF%BC%9A%E6%95%B0%E5%AD%97%2F%E7%BB%93%E8%AE%BA%2F%E8%83%BD%E5%8A%9B%22%5D%0A%20%20MET%20--%3E%20GOAL%0A%20%20GOAL%20--%3E%20CRIT%5B%22%E5%AE%B9%E5%B7%AE%E4%B8%8E%E9%AA%8C%E6%94%B6%E5%88%A4%E6%8D%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[r("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"类型与容差之所以是第一决定，因为它们定义了「失败」这个词。结果复现失败，怀疑次序是环境、依赖、数据版本，最后才是论文错误；方法复现失败，怀疑次序正好倒过来。把两类混在一次实验里（用作者代码加自己的数据，或用自己的实现加作者种子），失败时两头都无法归因——这是复现新手最常见的死法。",-1)),(e(),n(i,null,{default:a(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%A4%8D%E7%8E%B0%E5%A4%B1%E8%B4%A5%E4%BA%86%EF%BC%8C%E5%85%88%E6%80%80%E7%96%91%E8%B0%81%22%5D%20--%3E%20R%5B%22%E7%BB%93%E6%9E%9C%E5%A4%8D%E7%8E%B0%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E5%85%88%E6%9F%A5%EF%BC%9A%E7%8E%AF%E5%A2%83%E4%B8%8E%E4%BE%9D%E8%B5%96%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E5%86%8D%E6%9F%A5%EF%BC%9A%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%E4%B8%8E%E7%A7%8D%E5%AD%90%22%5D%0A%20%20R2%20--%3E%20R3%5B%22%E6%9C%80%E5%90%8E%E6%89%8D%E6%80%80%E7%96%91%E8%AE%BA%E6%96%87%E6%9C%AC%E8%BA%AB%22%5D%0A%20%20F%20--%3E%20M%5B%22%E6%96%B9%E6%B3%95%E5%A4%8D%E7%8E%B0%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20M%20--%3E%20M1%5B%22%E5%85%88%E6%9F%A5%EF%BC%9A%E8%87%AA%E5%B7%B1%E7%9A%84%E9%9A%90%E6%80%A7%E5%86%B3%E7%AD%96%E8%A1%A5%E5%AF%B9%E4%BA%86%E6%B2%A1%22%5D%0A%20%20M1%20--%3E%20M2%5B%22%E5%86%8D%E6%9F%A5%EF%BC%9A%E8%AE%BA%E6%96%87%E6%8A%AB%E9%9C%B2%E7%BC%BA%E5%8F%A3%E7%9A%84%E5%A4%84%E7%90%86%22%5D%0A%20%20M2%20--%3E%20M3%5B%22%E5%BE%88%E5%8F%AF%E8%83%BD%E6%8C%87%E5%90%91%E8%AE%BA%E6%96%87%E8%BF%87%E6%8B%9F%E5%90%88%E5%85%B6%E8%AF%84%E6%B5%8B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">常见误区：图省事用作者的代码配自己的数据，或用自己实现配作者的种子——两类实验混在一起，失败时两头都无法归因。省下的是半天拆分工作，赔进去的可能是整个归因预算。</span></p><p>目标线之间有包含关系，判定强度递减：数字对上是强证据，排序对上是中等证据，定性对上只是弱证据。下游引用你的复现时按档位取用，所以声明里必须写清楚停在哪条线，而不是让人误以为你验证了数字。</p><p><span class="marginnote">Henderson 等 2018 在深度强化学习里发现：同一算法、同一环境，不同独立实现之间的最终回报差异，大到能覆盖论文之间声称的差异——方法复现的结论线在方差大的领域里，比数字线更诚实，也更需要多种子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>复现不是逐位一致：跨硬件与并行训练下逐位一致本身是一门独立工程，低精度数值的<a href="/llm/num-crosshardware-consistency">跨硬件的数值一致性</a>另有专门讨论；本课程的「对上」一律指统计意义上的容差。复现也不是抄实现：方法复现的价值恰恰在于独立实现会暴露论文没写的决策。复现更不是重新调参超过原文——那是改进，要另立账本，混进复现报告会让「对上了」三个字失去含金量。刷榜不是复现：榜单只证明存在一组配置能到那个分数，不证明论文的训练路径可重走。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复现先分类：结果复现（同实现重跑）与方法复现（独立实现同结论），失败含义相反。</li><li>目标分三线：数字线最强、结论线居中、能力线最弱，判定强度递减。</li><li>开工前写一页声明：类型、目标线、容差、范围、约束；后课所有锚点与预算指回它。</li><li>混合两类实验会让失败无法归因；声明先行是第一纪律。</li><li>出处：Popper, <em>The Logic of Scientific Discovery</em>, 1959；Claerbout 与 Karrenbach, 1992；Henderson 等, Deep Reinforcement Learning that Matters, 2018；Gundersen 与 Kjensmo, 2018。</li></ul>',7))])}const F=l(d,[["render",D]]);export{_ as __pageData,F as default};
